css:
/* Style the text loader with an animated underline */
.text-loader {
  width: fit-content; /* Adjust width to content size */
  font-weight: bold; /* Bold text for emphasis */
  font-family: sans-serif; /* Clean, modern font */
  font-size: 30px; /* Readable size */
  padding-bottom: 8px; /* Space for the underline */
  background: linear-gradient(currentColor 0 0) 0 100% / 0% 3px no-repeat; /* Gradient underline, starts at 0% width */
  animation: expandUnderline 2s linear infinite; /* Animate underline growth */
}

/* Add the "Loading..." text via pseudo-element */
.text-loader::before {
  content: "Loading..."; /* Default text content */
}

/* Define the underline expansion animation */
@keyframes expandUnderline {
  to { background-size: 100% 3px; } /* Grow underline to full width */
}
